document.addEventListener("DOMContentLoaded",()=>{["jan","feb","mar","apr","may","jun","jul"].forEach(n=>{const e=document.getElementById(n);if(!e)return;const t=e.querySelector(".month-sub-nav");if(!t)return;const i=t.querySelectorAll(".sub-tab-btn"),s=e.querySelectorAll(".sub-tab-panel");i.forEach(r=>{r.addEventListener("click",()=>{i.forEach(o=>o.classList.remove("active")),r.classList.add("active");const d=r.getAttribute("data-subtab");s.forEach(o=>o.classList.remove("active"));const c=e.querySelector("#"+d);c&&(c.classList.add("active"),d.endsWith("-quiz")&&p(n))})})});const l={};function p(n){if(l[n])return;const e=window.quizData?window.quizData[n]:[];!e||e.length===0||(l[n]={currentIndex:0,score:0,answers:new Array(e.length).fill(null),questions:e},u(n))}function u(n){const e=l[n],t=e.questions[e.currentIndex],s=document.getElementById(n).querySelector("#"+n+"-quiz");s.querySelector(".quiz-progress").textContent=`Question ${e.currentIndex+1} of ${e.questions.length}`,s.querySelector(".quiz-score").textContent=`Score: ${e.score}/${e.answers.filter(o=>o!==null).length}`,s.querySelector(".quiz-progress-fill").style.width=`${(e.currentIndex+1)/e.questions.length*100}%`,s.querySelector(".quiz-question-text.en-text").innerHTML=t.question_en,s.querySelector(".quiz-question-text.hi-text").innerHTML=t.question_hi;const r=s.querySelector(".quiz-options-list");r.innerHTML="",(t.type==="tf"?[{key:"A",en:"True",hi:"\u0938\u0924\u094D\u092F"},{key:"B",en:"False",hi:"\u0905\u0938\u0924\u094D\u092F"}]:t.options).forEach(o=>{const a=document.createElement("button");a.className="quiz-option-btn",a.innerHTML=`<span class="option-marker">${o.key}</span>
            <div>
              <span class="en-text">${o.en}</span>
              <span class="hi-text">${o.hi}</span>
            </div>`;const q=e.answers[e.currentIndex];q!==null?(a.disabled=!0,o.key===t.correct_option?a.classList.add("correct"):o.key===q&&a.classList.add("wrong")):a.addEventListener("click",()=>x(n,o.key)),r.appendChild(a)});const c=s.querySelector(".quiz-explanation-box");e.answers[e.currentIndex]!==null?(c.style.display="block",c.querySelector(".explanation-text.en-text").textContent=t.explanation_en,c.querySelector(".explanation-text.hi-text").textContent=t.explanation_hi):c.style.display="none",s.querySelector(".prev-btn").disabled=e.currentIndex===0,s.querySelector(".next-btn").disabled=e.currentIndex===e.questions.length-1}function x(n,e){const t=l[n],i=t.questions[t.currentIndex];t.answers[t.currentIndex]=e,e===i.correct_option&&t.score++,u(n)}document.addEventListener("click",n=>{const e=n.target.closest(".prev-btn"),t=n.target.closest(".next-btn");if(e){const s=e.closest(".tab-panel").id,r=l[s];r&&r.currentIndex>0&&(r.currentIndex--,u(s))}if(t){const s=t.closest(".tab-panel").id,r=l[s];r&&r.currentIndex<r.questions.length-1&&(r.currentIndex++,u(s))}})});
